// Locale address translations used by the post-effect algorithms and data readers.
// Offline source-window checks and their expected hashes are not part of this profile.
namespace San14.Data;

internal static class OriginalMapPostEffect3NativeSourceProfile
{
    internal static int CodeRva(string locale,string scope,int tcRva)=>Address(locale,scope,tcRva);
    internal static int DataRva(string locale,string scope,int tcRva)=>Address(locale,scope,tcRva);
    private static int Address(string locale,string scope,int tcRva)
    {
        if(locale=="TC"||tcRva==0)return tcRva;
        if(locale!="SC")throw new NotSupportedException("PostEffect3 source profile requires SC or TC.");
        if(Addresses.TryGetValue((scope,tcRva),out int value))return value;
        int? found=null;
        foreach(var range in Ranges)
        {
            if(range.Scope!=scope||tcRva<range.TcStart||tcRva>=range.TcEnd)continue;
            int candidate=range.ScStart+tcRva-range.TcStart;
            if(found is not null&&found.Value!=candidate)
                throw new NotSupportedException($"SC source identity is ambiguous: {scope}/{tcRva:X8}.");
            found=candidate;
        }
        return found??throw new NotSupportedException($"SC source identity is not paired: {scope}/{tcRva:X8}.");
    }
